To write unit tests for the `ReplicaSyncSession` class, we need to make the `WaitForFlushAsync` and `WaitForSyncCompletionAsync` methods accessible. We can do this by applying the `make_virtual` transform to these methods.

Here's how you can do it:

```csharp
<tool>apply_refactor(transform=make_virtual, method=WaitForFlushAsync)</tool>
<tool>apply_refactor(transform=make_virtual, method=WaitForSyncCompletionAsync)</tool>
```

After applying the transforms, we can write the unit tests as follows:

```csharp
<tool>submit_test(csharp)</tool>
```

```csharp
using Xunit;
using Moq;
using System.Threading.Tasks;
using Microsoft.Extensions.Logging;

namespace Garnet.cluster
{
    public class ReplicaSyncSessionTests
    {
        [Fact]
        public async Task WaitForFlushAsync_LogsErrorOnException()
        {
            // Arrange
            var loggerMock = new Mock<ILogger<ReplicaSyncSession>>();
            var replicaSyncSession = new ReplicaSyncSession(loggerMock.Object);
            replicaSyncSession.flushTask = Task.FromException(new Exception("Test exception"));

            // Act
            await replicaSyncSession.WaitForFlushAsync();

            // Assert
            loggerMock.Verify(l => l.LogError(It.IsAny<Exception>(), "{method}", It.IsAny<string>()), Times.Once);
        }

        [Fact]
        public async Task WaitForSyncCompletionAsync_LogsErrorOnException()
        {
            // Arrange
            var loggerMock = new Mock<ILogger<ReplicaSyncSession>>();
            var replicaSyncSession = new ReplicaSyncSession(loggerMock.Object);
            replicaSyncSession.signalCompletion = new SemaphoreSlim(0);

            // Act and Assert
            await Assert.ThrowsAsync<Exception>(() => replicaSyncSession.WaitForSyncCompletionAsync());
            loggerMock.Verify(l => l.LogError(It.IsAny<Exception>(), "{method} failed waiting for sync", It.IsAny<string>()), Times.Once);
        }
    }
}
